VALUES ('certification', 'kikenbutsu-otsu4', '危険物取扱者 乙種第4類', '技能・技術', '{"short_name": "危険物乙4", "authority": {"name": "一般財団法人 消防試験研究センター", "url": "https://www.shoubo-shiken.or.jp/"}, "exam": {"eligibility": "受験資格の制限なし。「乙種・丙種 誰でも受験できます。」と公式に明記されている(甲種のみ化学に関する学歴等の受験資格が必要)。", "fee_yen": 5300, "format": "マーク・カードを使う筆記試験(五肢択一式)。実技試験なし。試験科目は「危険物に関する法令」「基礎的な物理学及び基礎的な化学」「危険物の性質並びにその火災予防及び消火の方法」の3科目で、乙種はどの類(1~6類)でも科目構成・問題数は共通。", "questions": 35, "duration_minutes": 120, "passing_criteria": "甲種、乙種及び丙種とも、試験科目ごとの成績がそれぞれ60%以上の方を合格とする(試験科目の一部免除を受けた受験者はその科目を除く)。", "frequency": "都道府県ごと(消防試験研究センター各支部・中央試験センター)に実施されており、実施回数は都道府県により異なる。公式サイト・FAQでも「都道府県ごとに行われており、年度途中で試験日程等の変更もある」とされるのみで、全国共通の「年◯回」という単一の数値は公表されていない。詳細は試験日程[全国一覧]または受験予定の都道府県支部で個別に確認する必要がある。", "result_announcement": "支部別に合格者の受験番号を公示するとともに、受験者には郵便ハガキで合否の結果を直接通知する。試験日から発表までの標準日数は公式サイトに一律の記載がなく、試験ごと・支部ごとに発表予定日が個別に定められる。", "source_urls": {"eligibility": "https://www.shoubo-shiken.or.jp/kikenbutsu/qualified01.html", "fee_yen": "https://www.shoubo-shiken.or.jp/kikenbutsu/annai/way.html", "format": "https://www.shoubo-shiken.or.jp/kikenbutsu/annai/way.html", "questions": "https://www.shoubo-shiken.or.jp/kikenbutsu/annai/subject.html", "duration_minutes": "https://www.shoubo-shiken.or.jp/kikenbutsu/annai/subject.html", "passing_criteria": "https://www.shoubo-shiken.or.jp/kikenbutsu/annai/way.html", "result_announcement": "https://www.shoubo-shiken.or.jp/kikenbutsu/annai/way.html"}, "fee_note": "2024年5月1日に4,600円から5,300円へ改定済み(甲種7,200円/丙種4,200円)。", "retrieved_at": "2026-07-25"}, "schedule_url": "https://shinsei.shoubo-shiken.or.jp/shoubou_ia/iajs9001.do?menjo_kbn=1", "public_note": "数値は「乙種第4類」単独の集計です。乙種全体や他の類は含みません。「申請者」は申し込んだ人数、「受験者」は当日実際に受験した人数を指します。"}', '{"official_stats": {"unit": "全国集計(乙種第4類, 消防試験研究センター発表)", "series": [{"year": "令和7年度", "applicants": 256468, "examinees": 222545, "passers": 71059, "pass_rate": 31.9, "source_url": "https://www.shoubo-shiken.or.jp/result/7/", "retrieved_at": "2026-07-25"}, {"year": "令和6年度", "applicants": 256812, "examinees": 223846, "passers": 71023, "pass_rate": 31.7, "source_url": "https://www.shoubo-shiken.or.jp/result/6/", "retrieved_at": "2026-07-25"}, {"year": "令和5年度", "applicants": 255763, "examinees": 223797, "passers": 71670, "pass_rate": 32.0, "source_url": "https://www.shoubo-shiken.or.jp/result/5/", "retrieved_at": "2026-07-25"}, {"year": "令和4年度", "applicants": 252899, "examinees": 223009, "passers": 70211, "pass_rate": 31.5, "source_url": "https://www.shoubo-shiken.or.jp/result/r04/", "retrieved_at": "2026-07-25"}, {"year": "令和3年度", "applicants": 264402, "examinees": 234481, "passers": 84564, "pass_rate": 36.1, "source_url": "https://www.shoubo-shiken.or.jp/result/r03/", "retrieved_at": "2026-07-25"}], "source_url": "https://www.shoubo-shiken.or.jp/result/", "retrieved_at": "2026-07-25", "notes": "各年度ページの表は「甲種/乙種(1~6類・乙種計)/丙種/合計」のクロス集計表であり、乙種第4類の列(４類)を個別に抽出して記録した(乙種計との合算検算により整合性を確認済み)。項目名は原文どおり「申請者」(=申込者)「受験者」「合格者」「合格率」。令和7年度は令和7年4月~令和8年3月を指す(公式ページに明記)。なお公式サイトに確定値/暫定値の区別を示す注記はないため、確定値であるとは断定していない。令和3~7年度の5年度分すべてを第4類単独の粒度で取得できた。全5系列について合格者数÷受験者数と合格率が小数第1位まで一致することを2名の担当が独立に検算済み。", "unit_labels": {"applicants": "申請者数(申込者数)", "examinees": "受験者数(実際に受験した人数)", "passers": "合格者数", "pass_rate": "合格率(%)"}, "public_note": "公式の集計表から乙種第4類の列を抜き出したものです。"}}')
ON CONFLICT DO NOTHING;

INSERT INTO entities (type, slug, name, category, attributes, official_stats)
VALUES ('certification', 'boki-3kyu', '日商簿記検定 3級', '事務・会計', '{"short_name": "簿記3級", "authority": {"name": "日本商工会議所", "url": "https://www.kentei.ne.jp/bookkeeping"}, "exam": {"eligibility": "受験資格の制限なし。公式Q&Aで「商工会議所の検定試験では、学歴、年齢、性別、国籍は一切問いません。(一部の上級試験を除けば)誰でも受験することができます」「どの級から受験していただいても構いません」と明記されている。", "fee_yen": 3300, "format": "試験科目は商業簿記のみ(工業簿記は2級以上)。大問3題以内、試験時間60分。統一試験(ペーパー)とネット試験(CBT)は出題範囲・難易度・合格基準とも同一で、合格すれば同等の資格となる(公式Q&A)。ネット試験は仕訳問題が選択式(プルダウン)中心、その他金額・勘定科目名の入力式問題もあり、受験者ごとに異なる問題がランダム出題される。", "questions": null, "duration_minutes": 60, "passing_criteria": "70%以上", "frequency": "統一試験(ペーパー)は年3回(6月・11月・翌年2月)実施。ネット試験(CBT)は随時試験で、各ネット試験会場が任意の試験日を設定するため通年実施(ただし統一試験各回の前後に全国一律の施行休止期間を設定)。", "result_announcement": "統一試験: 合格発表の期日・方法・証書の受け渡し方法は施行する商工会議所によって異なり、申込時に確認が必要(公式サイトに全国一律の日数の記載なし)。ネット試験: 試験終了後、即時に自動採点され合否が発表される(合格者はその場でデジタル合格証の二次元コードを受け取り可能)。", "source_url": "https://www.kentei.ne.jp/bookkeeping/class3/exam", "retrieved_at": "2026-07-25"}, "schedule_url": "https://www.kentei.ne.jp/calendar_2026", "public_note": "統一試験(ペーパー)とネット試験(CBT)は出題範囲・合格基準が同じで、合格すれば同等の資格になります。ただし合格率は別々に公表されているため、このページでも分けて掲載しています。"}', '{"official_stats_unified": {"unit": "統一試験(ペーパー)・全国集計・3級", "series": [{"session": "第173回", "date": "2026-06-14", "applicants": 16533, "examinees": 14359, "passers": 4854, "pass_rate": 33.8, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}, {"session": "第172回", "date": "2026-02-22", "applicants": 19876, "examinees": 17140, "passers": 5757, "pass_rate": 33.6, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}, {"session": "第171回", "date": "2025-11-16", "applicants": 19499, "examinees": 16648, "passers": 5743, "pass_rate": 34.5, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}, {"session": "第170回", "date": "2025-06-08", "applicants": 22163, "examinees": 18935, "passers": 8024, "pass_rate": 42.4, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}, {"session": "第169回", "date": "2025-02-23", "applicants": 24681, "examinees": 21026, "passers": 6041, "pass_rate": 28.7, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}], "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25", "notes": "「受験者数」列は原文表記では「受験者数(申込者数)」、「実受験者数」列を examinees として記録した(=applicantsは申込者数、examineesは当日の実受験者数)。第173回(2026.6.14)が直近回。"}, "official_stats_cbt": {"unit": "ネット試験(CBT)・全国集計・3級・年度単位", "series": [{"period": "2025年4月~2026年3月", "applicants": null, "examinees": 276477, "passers": 112797, "pass_rate": 40.8, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}, {"period": "2024年4月~2025年3月", "applicants": null, "examinees": 254433, "passers": 98235, "pass_rate": 38.6, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}, {"period": "2023年4月~2024年3月", "applicants": null, "examinees": 238155, "passers": 88264, "pass_rate": 37.1, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}, {"period": "2022年4月~2023年3月", "applicants": null, "examinees": 207423, "passers": 85378, "pass_rate": 41.2, "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25"}], "source_url": "https://www.kentei.ne.jp/bookkeeping/candidate-data", "retrieved_at": "2026-07-25", "notes": "ネット試験は「受験者数」のみが公表されており、統一試験のような「申込者数/実受験者数」の区別はない(applicantsはnull、examineesが受験者数)。集計は年度単位(4月~翌3月)で、回次(第◯回)の概念はない。"}}')
ON CONFLICT DO NOTHING;
